-- Expand the free practice bank; each visit continues to contain three questions.
INSERT INTO public.answer_trap_questions (question_stem, options, correct_answer, trap_type, trap_display_name, key_cue, why_correct_short, why_wrong_short, one_line_fix, difficulty, is_active)
VALUES
('An adult taking digoxin has a potassium level of 3.0 mEq/L. Which new finding most strongly suggests digoxin toxicity?', '[{"label": "A", "text": "Increased appetite and weight gain"}, {"label": "B", "text": "Seeing yellow-green halos around lights"}, {"label": "C", "text": "Increased urine output"}, {"label": "D", "text": "An unchanged pulse of 76/min"}]'::jsonb, 'B', 'Medication reasoning', 'Digoxin toxicity', 'Potassium is low, and the visual disturbance is new.', 'Yellow-green color changes and halos are recognized digoxin adverse effects that raise concern for toxicity. Low potassium increases susceptibility; toxicity can occur at lower serum digoxin concentrations.', 'Loss of appetite, nausea, and vomiting are associated with toxicity; increased appetite is not the characteristic finding. Increased urine output alone is not a characteristic toxicity sign and may reflect another treatment or improved circulation. An unchanged pulse of 76/min does not suggest a new rhythm disturbance. New bradycardia or heart block would also warrant concern; it should not be dismissed as harmless.', 'Connect new visual, gastrointestinal, or rhythm changes with medication and electrolyte risk; no single sign proves toxicity.', 3, true),
('A nurse wore gloves, a gown, a face shield, and a mask while providing care. Using CDC’s sequence for removing these PPE items separately, which item is removed first?', '[{"label": "A", "text": "Gloves"}, {"label": "B", "text": "Gown"}, {"label": "C", "text": "Face shield"}, {"label": "D", "text": "Mask"}]'::jsonb, 'A', 'Safety', 'Safe PPE removal', 'The question specifies removal of PPE items separately.', 'In CDC’s separate-item sequence, gloves are removed first, followed by eye protection, gown, and mask or respirator. Use the prescribed technique to avoid touching contaminated surfaces.', 'Gown removal comes after gloves and eye protection in this specified sequence. A different CDC method removes gown and gloves together. The face shield is removed after gloves in the separate-item sequence, using its clean headband rather than the contaminated front. The mask is removed later by its ties or elastics. Removing it first does not follow this specified sequence.', 'Follow the specified PPE technique and local policy; perform hand hygiene after removal and between steps if hands become contaminated.', 3, true),
('An RN assigns care for stable medical-surgical patients. The LPN is authorized and competent to give oral medications under local scope and facility policy; the UAP has no medication-administration authorization. Which assignment is appropriate?', '[{"label": "A", "text": "Have the UAP provide initial teaching about a low-sodium diet"}, {"label": "B", "text": "Have the UAP independently assess pain and decide whether treatment is effective"}, {"label": "C", "text": "Have the LPN administer scheduled oral medications to a stable patient"}, {"label": "D", "text": "Have the LPN independently complete the comprehensive admission assessment and establish the nursing care plan"}]'::jsonb, 'C', 'Delegation', 'Assigning RN, LPN, and UAP care', 'The patient is stable, and the LPN’s medication task is authorized.', 'Scheduled oral medication administration fits the LPN’s stated scope and competency. The RN remains responsible for appropriate assignment, supervision, and follow-up.', 'Initial teaching requires nursing judgment; it is not assigned to this UAP. Reinforcing established instructions is different from developing teaching. The UAP may collect and report authorized observations, but independent nursing assessment and evaluation require a licensed nurse. The comprehensive assessment and independent nursing care plan require RN judgment in this scenario. An LPN may contribute focused assessments and data within local scope.', 'Match the patient and task to local scope, demonstrated competence, and supervision; collecting data is different from independent nursing judgment.', 3, true),
('The nurse has four assigned patients. Which patient should the nurse assess first?', '[{"label": "A", "text": "A patient with blood pressure 150/92 mm Hg and no symptoms"}, {"label": "B", "text": "A postoperative patient with new inspiratory stridor"}, {"label": "C", "text": "A stable patient with a stage 2 pressure injury requesting a scheduled dressing change"}, {"label": "D", "text": "A patient with mild nausea after an antiemetic and no other symptoms"}]'::jsonb, 'B', 'Priority-setting', 'Recognizing a threatened airway', 'The postoperative patient has new inspiratory stridor.', 'New inspiratory stridor suggests upper-airway narrowing and may indicate an impending airway emergency. It takes priority over the stable findings listed.', 'The elevated blood pressure needs follow-up, but the scenario describes no acute symptoms or threatened airway. The dressing change is needed, but routine wound care can wait while the nurse assesses a possible airway emergency. Mild nausea without other symptoms is less urgent than new stridor.', 'Prioritize a new, potentially time-sensitive threat over stable findings; seek immediate help when airway compromise is suspected.', 3, true),
('A patient with type 1 diabetes has a prescribed subcutaneous mealtime dose of insulin lispro (Humalog). The nurse has checked glucose, confirmed the dose is appropriate under the order, and verified that the patient can eat. When should the premeal dose be administered?', '[{"label": "A", "text": "30 to 60 minutes before the meal"}, {"label": "B", "text": "Only if premeal glucose exceeds 200 mg/dL, regardless of the order"}, {"label": "C", "text": "At bedtime regardless of meals"}, {"label": "D", "text": "When the meal is available and the patient is ready to eat, within 15 minutes before the meal"}]'::jsonb, 'D', 'Medication reasoning', 'Timing mealtime insulin', 'The prescribed product is insulin lispro, and the patient is ready to eat.', 'Humalog’s labeled subcutaneous timing is within 15 minutes before a meal or immediately after a meal. For this premeal dose, ensure food is available and the patient is ready to eat.', 'This is too early for the specified lispro premeal dose. Regular human insulin has different labeled timing, approximately 30 minutes before meals. A scheduled mealtime dose is not governed by an invented 200 mg/dL cutoff. Follow the individual prescription, glucose result, and meal-intake plan. Mealtime lispro must be coordinated with food and the prescription. A basal or separately prescribed correction dose is a different purpose.', 'Check the exact insulin product, order, glucose, and readiness to eat; rapid-acting products do not all have identical timing.', 3, true)
